# shellcheck shell=bash disable=SC2154  # variables come from apply-theme.sh and the earlier parts
# scripts/theme.d/04-rofi.sh: part of apply-theme.sh, sourced in order in the same shell (not run on its own)
# ==========================================
# 4. Rofi
# ==========================================
cat <<EOF > "$CACHE_DIR/rofi.rasi"
* {
    bg:        $BG;
    bg-alt:    $BG_ALT;
    bg-visual: $BG_VISUAL;
    fg:        $FG;
    muted:     $FG_MUTED;
    accent:    $ACCENT;
    background-color: @bg;
    text-color: @fg;
}
EOF

cat <<EOF > "$CACHE_DIR/rofi-font.rasi"
/* Generated by apply-theme.sh: active font ($FONT_NAME) */
configuration { font: "$FONT_UI 11"; }
EOF

# Fontconfig (included by ~/.config/fontconfig/fonts.conf): the active font is the default for
# sans-serif / serif / monospace and replaces common fonts that web pages ask for by name
cat <<EOF > "$CACHE_DIR/fonts.conf"
<?xml version="1.0"?>
<!DOCTYPE fontconfig SYSTEM "urn:fontconfig:fonts.dtd">
<!-- Generated by apply-theme.sh: active font $FONT_NAME -->
<fontconfig>
  <alias binding="strong"><family>sans-serif</family><prefer><family>$FONT_UI</family><family>Noto Color Emoji</family></prefer></alias>
  <alias binding="strong"><family>serif</family><prefer><family>$FONT_UI</family><family>Noto Color Emoji</family></prefer></alias>
  <alias binding="strong"><family>monospace</family><prefer><family>$FONT_MONO</family><family>Noto Color Emoji</family></prefer></alias>
  <match target="pattern"><test name="family"><string>Arial</string></test><edit name="family" mode="assign" binding="strong"><string>$FONT_UI</string></edit></match>
  <match target="pattern"><test name="family"><string>Helvetica</string></test><edit name="family" mode="assign" binding="strong"><string>$FONT_UI</string></edit></match>
  <match target="pattern"><test name="family"><string>Helvetica Neue</string></test><edit name="family" mode="assign" binding="strong"><string>$FONT_UI</string></edit></match>
  <match target="pattern"><test name="family"><string>Verdana</string></test><edit name="family" mode="assign" binding="strong"><string>$FONT_UI</string></edit></match>
  <match target="pattern"><test name="family"><string>Tahoma</string></test><edit name="family" mode="assign" binding="strong"><string>$FONT_UI</string></edit></match>
  <match target="pattern"><test name="family"><string>Segoe UI</string></test><edit name="family" mode="assign" binding="strong"><string>$FONT_UI</string></edit></match>
  <match target="pattern"><test name="family"><string>Roboto</string></test><edit name="family" mode="assign" binding="strong"><string>$FONT_UI</string></edit></match>
  <match target="pattern"><test name="family"><string>Open Sans</string></test><edit name="family" mode="assign" binding="strong"><string>$FONT_UI</string></edit></match>
  <match target="pattern"><test name="family"><string>Liberation Sans</string></test><edit name="family" mode="assign" binding="strong"><string>$FONT_UI</string></edit></match>
  <match target="pattern"><test name="family"><string>DejaVu Sans</string></test><edit name="family" mode="assign" binding="strong"><string>$FONT_UI</string></edit></match>
  <match target="pattern"><test name="family"><string>Times New Roman</string></test><edit name="family" mode="assign" binding="strong"><string>$FONT_UI</string></edit></match>
  <match target="pattern"><test name="family"><string>Georgia</string></test><edit name="family" mode="assign" binding="strong"><string>$FONT_UI</string></edit></match>
  <match target="pattern"><test name="family"><string>Liberation Serif</string></test><edit name="family" mode="assign" binding="strong"><string>$FONT_UI</string></edit></match>
  <match target="pattern"><test name="family"><string>DejaVu Serif</string></test><edit name="family" mode="assign" binding="strong"><string>$FONT_UI</string></edit></match>
  <match target="pattern"><test name="family"><string>Courier</string></test><edit name="family" mode="assign" binding="strong"><string>$FONT_MONO</string></edit></match>
  <match target="pattern"><test name="family"><string>Courier New</string></test><edit name="family" mode="assign" binding="strong"><string>$FONT_MONO</string></edit></match>
  <match target="pattern"><test name="family"><string>Consolas</string></test><edit name="family" mode="assign" binding="strong"><string>$FONT_MONO</string></edit></match>
  <match target="pattern"><test name="family"><string>Menlo</string></test><edit name="family" mode="assign" binding="strong"><string>$FONT_MONO</string></edit></match>
  <match target="pattern"><test name="family"><string>Monaco</string></test><edit name="family" mode="assign" binding="strong"><string>$FONT_MONO</string></edit></match>
  <match target="pattern"><test name="family"><string>Liberation Mono</string></test><edit name="family" mode="assign" binding="strong"><string>$FONT_MONO</string></edit></match>
  <match target="pattern"><test name="family"><string>DejaVu Sans Mono</string></test><edit name="family" mode="assign" binding="strong"><string>$FONT_MONO</string></edit></match>
</fontconfig>
EOF

# Minimal single-colour app icons for Rofi (icon theme ColorEngine-Apps), in the soft accent
bash "$DOTFILES_DIR/scripts/rofi-icons.sh" "$ACCENT_SOFT" || echo "[!] Rofi icons could not be generated." >&2

